      "Roof Replacement",
      "Roof Repair",
      "Storm Damage Restoration",
      "New Construction Roofing",
      "Flat Roofing",
      "Roof Inspections and Video Roof Assessments"
    ],
    "claims": [
      {
        "statement": "The company operates as a professional residential and commercial roofing contractor in Southwest Idaho.",
        "label": "fact",
        "sourceUrl": "https://www.idahoroofingcontractors.com/",
        "quote": "Idaho Roofing Contractors is a professional residential and commercial roofing company serving communities throughout Southwest Idaho for 25+ years."
      },
      {
        "statement": "The firm performs roof replacements, new installations, and storm damage restoration work.",
        "label": "fact",
        "sourceUrl": "https://www.idahoroofingcontractors.com/",
        "quote": "We can handle roof replacements, new installations, storm damage restorations, and more."
      }
    ]
  },
  "publicInformation": {
    "officialWebsite": "https://www.idahoroofingcontractors.com/",
    "claims": [
      {
        "statement": "The business originated in 2001 and has grown across the Treasure Valley over more than two decades.",
        "label": "fact",
        "sourceUrl": "https://www.idahoroofingcontractors.com/about-us/",
        "quote": "Idaho Roofing Contractors has served the Treasure Valley since 2001. What began in a garage in Kuna has grown into one of the most trusted"
      },
      {
        "statement": "The company is an Owens Corning Platinum Preferred Contractor with a Better Business Bureau A+ rating.",
        "label": "fact",
        "sourceUrl": "https://www.idahoroofingcontractors.com/",
        "quote": "Idaho Roofing Contractors holds an A+ rating with the Better Business Bureau. We’re also a member of the Boise Metro Chamber."
      }
    ]
  },
  "licensing": {
    "claims": [
      {
        "statement": "The business operates under Idaho contractor registration license number RCE-5471.",
        "label": "fact",
        "sourceUrl": "https://www.idahoroofingcontractors.com/faq/",
        "quote": "Idaho Roofing Contractors is fully licensed and insured in the state of Idaho (License No. RCE-5471)."
      },
      {
        "statement": "The contractor maintains general liability and workers compensation insurance policies.",
        "label": "fact",
        "sourceUrl": "https://www.idahoroofingcontractors.com/faq/",
        "quote": "We carry all required liability and workers compensation coverage on every job, giving you complete peace of mind throughout the project."
      }
    ],
    "limitations": "Licensing information was evaluated solely from public disclosures on the company's official website; third-party verification via the Idaho Division of Occupational and Professional Licenses (dopl.idaho.gov) was not independently conducted."
  },
  "existingSoftware": [
    {
      "product": "AccuLynx",
      "purpose": "Roofing field-service CRM and web lead capture",
      "evidence": {
        "statement": "The website connects to leads.acculynx.com, which is understood to be the AccuLynx roofing contractor CRM software for lead capture.",
        "label": "hypothesis",
        "sourceUrl": null,
        "quote": null
      }
    },
    {
      "product": "Roofle (Roof Quote PRO)",
      "purpose": "Instant online roofing quote widget and automated lead capture",
      "evidence": {
        "statement": "The homepage loads a script from app.roofle.com titled roof-quote-pro-widget.js, representing the Roofle Roof Quote PRO software.",
        "label": "hypothesis",
        "sourceUrl": null,
        "quote": null
      }
    },
    {
      "product": "Simpli.fi",
      "purpose": "Programmatic advertising and digital audience tracking",
      "evidence": {
        "statement": "The website includes script calls to tag.simpli.fi, which represents the Simpli.fi advertising attribution and tracking platform.",
        "label": "hypothesis",
        "sourceUrl": null,
        "quote": null
      }
    },
    {
      "product": "Google Ads and Google Tag Manager",
      "purpose": "Paid advertising tracking and site analytics",
      "evidence": {
        "statement": "The company's privacy policy explicitly notes the use of Google Ads for digital advertising.",
        "label": "fact",
        "sourceUrl": "https://www.idahoroofingcontractors.com/privacy-policy/",
        "quote": "Google, as a third party vendor, uses cookies to serve ads."
      }
    },
    {
      "product": "Birdeye",
      "purpose": "Customer review generation and website display",
      "evidence": {
        "statement": "The company's about page embeds a script from birdeye.com, representing the Birdeye reputation management widget.",
        "label": "hypothesis",
        "sourceUrl": null,
        "quote": null
      }
    }
  ],
  "opportunityEvidence": [
    {
      "statement": "The business pledges fast response times and direct contact with local roofing specialists rather than a call center.",
      "label": "fact",
      "sourceUrl": "https://www.idahoroofingcontractors.com/contact-us/",
      "quote": "When you reach out, you’ll speak with a local roofing professional — not a call center. We’ll answer your questions, schedule appointments quickly"
    },
    {
      "statement": "The website incorporates dedicated roofing lead-intake infrastructure linking directly to external roofing CRM endpoints.",
      "label": "inference",
      "sourceUrl": "https://www.idahoroofingcontractors.com/",
      "quote": null
    },
    {
      "statement": "Residential roof replacements in the Boise area typically range between $10,000 and $15,000.",
      "label": "fact",
      "sourceUrl": "https://www.idahoroofingcontractors.com/faq/",
      "quote": "Most residential roof replacements in the Boise area run between $10,000 and $15,000, depending on the size of your home"
    }
  ],
  "problems": [
    {
      "problem": "Potential bottleneck in lead processing and appointment dispatch during major weather or hail damage surges.",
      "label": "hypothesis",
      "basis": "Roofing inquiries spike sharply following severe hail and wind storms, which could stress internal intake staff despite CRM integration."
    },
    {
      "problem": "Manual overhead in reporting marketing return across multi-channel ad campaigns (Simpli.fi, Google Ads, TVSquared) and AccuLynx booked jobs.",
      "label": "hypothesis",
      "basis": "Tracking script tags indicate spend across multiple digital ad networks, which frequently requires manual aggregation to calculate cost-per-booked job."
    },
    {
      "problem": "No verified lead leakage, pipeline gap, or responsiveness failure exists on the public website.",
      "label": "fact",
      "basis": "The website shows an active AccuLynx CRM integration, an instant Roofle quote widget, structured forms with SMS consent, and over 940 customer reviews with a 4.9 average."
    }
  ],
  "existingSolutions": [
    {
      "solution": "AccuLynx Roofing Software",
      "addresses": "Lead management, estimating, customer records, and job production tracking specifically designed for roofing contractors.",
      "alreadyOwned": true
    },
    {
      "solution": "Roofle Roof Quote PRO",
      "addresses": "Instant automated roof replacement estimates directly on the website to capture homeowner leads immediately.",
      "alreadyOwned": true
    },
    {
      "solution": "Simpli.fi and Google Tag Manager Analytics",
      "addresses": "Ad campaign conversion tracking and attribution.",
      "alreadyOwned": true
    }
  ],
  "forgexSolutions": [],
